document:
mutation ProductExport($input: ExportProductsInput!) {
  exportProducts(input: $input) {
    exportFile {
      ...ExportFile
    }
    errors {
      ...ExportError
    }
  }
}

fragment ExportFile on ExportFile {
  id
  status
  url
}

fragment ExportError on ExportError {
  code
  field
  message
}
